-- خِدْمَتي AI — Supabase Schema (كامل + آمن)
-- الملف ده بيتشغّل مرة واحدة في Supabase SQL Editor
-- https://supabase.com/dashboard/project/puhdastfiswcmbnczvwx/sql/new
-- آمن: كل الجداول if not exists + كل الـ INSERT on conflict do nothing
-- ============================================================

-- ============================================================
-- 1) جدول categories — أقسام الخدمات (13 قسم)
-- ============================================================
create table if not exists public.categories (
  id    text primary key,
  slug  text,
  name  text not null,
  icon  text,
  "desc"  text,
  color text
);

alter table public.categories enable row level security;
drop policy if exists "categories read all" on public.categories;
create policy "categories read all" on public.categories for select using (true);

insert into public.categories (id, slug, name, icon, "desc", color) values
