-- ============================================================
-- 2) جدول services — الخدمات (58 خدمة)
--    ملاحظة: العمود اسمه svc_desc (مش desc) لأن desc كلمة محجوزة في SQL
--    والـ app بياخد svc_desc ويعملها desc تلقائياً
-- ============================================================
create table if not exists public.services (
  id          bigint primary key,
  category    text,
  icon        text,
  name        text not null,
  svc_desc    text,
  online      boolean default true,
  link        text,
  source      text,
  updated     text,
  tags        text[],
  eligibility text,
  documents   text[],
  steps       text[],
  fees        text,
  duration    text
);

alter table public.services enable row level security;
drop policy if exists "services read all" on public.services;
create policy "services read all" on public.services for select using (true);

